
from datetime import datetime

from sqlalchemy import (
    Column,
    DateTime,
    Index,
    Integer,
    JSON,
    String,
    Text,
    UniqueConstraint,
    func,
)

from pgvector.sqlalchemy import Vector

from app.core.database import Base
from app.services.embedding_service import EMBEDDING_DIMENSION


class CodeChunk(Base):
    __tablename__ = "code_chunks"

    id = Column(Integer, primary_key=True, index=True)

    # Stable ID generated by our code chunker.
    chunk_id = Column(String(64), nullable=False)

    # Repository and source-file information.
    repository_path = Column(Text, nullable=False)
    file_path = Column(Text, nullable=False)

    # Chunk metadata.
    language = Column(String(50), nullable=False)
    chunk_index = Column(Integer, nullable=False)
    start_line = Column(Integer, nullable=False)
    end_line = Column(Integer, nullable=False)

    # Actual source code.
    content = Column(Text, nullable=False)

    # Embedding vector.
    embedding = Column(
        Vector(EMBEDDING_DIMENSION),
        nullable=False,
    )

    embedding_model = Column(
        String(100),
        nullable=False,
    )

    # Additional chunk metadata.
    chunk_metadata = Column(
        "metadata",
        JSON,
        nullable=False,
        default=dict,
    )

    created_at = Column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False,
    )

    __table_args__ = (
        UniqueConstraint(
            "repository_path",
            "chunk_id",
            name="uq_repository_chunk",
        ),
        Index(
            "ix_code_chunks_repository_file",
            "repository_path",
            "file_path",
        ),
    )
